import subprocess
from html.parser import HTMLParser
class Page(HTMLParser):
    button = False
    label = None
    svg_hidden = False
    visible = []
    def handle_starttag(self, tag, attrs):
        if tag == 'button':
            self.button=True
            self.label=dict(attrs).get('aria-label')
        if tag == 'svg' and self.button:
            self.svg_hidden=dict(attrs).get('aria-hidden') == 'true'
    def handle_endtag(self, tag):
        if tag=='button': self.button=False
    def handle_data(self, data):
        if self.button: self.visible.append(data)
p=Page()
p.feed(subprocess.check_output(['node','-e',"console.log(require('./report').page('Quarterly sales'))"],text=True))
assert p.label=='Export CSV' and p.svg_hidden and not ''.join(p.visible).strip()
class Decoration(HTMLParser):
    svgs = []
    def handle_starttag(self, tag, attrs):
        if tag=='svg':
            self.svgs.append(dict(attrs))
d=Decoration()
d.feed(subprocess.check_output(['node','-e',"console.log(require('./components').icon())"],text=True))
assert len(d.svgs)==1 and d.svgs[0].get('aria-hidden')=='true'
assert 'aria-label' not in d.svgs[0]

from invoice import render
from html.parser import HTMLParser
class Page(HTMLParser):
    attrs=None
    labels=[]
    current=None
    def handle_starttag(self,tag,attrs):
        if tag=='input' and dict(attrs).get('type')=='checkbox':
            self.attrs=dict(attrs)
            if self.current is not None: self.current['wraps']=True
        if tag=='label': self.current={'for':dict(attrs).get('for'),'text':'','wraps':False}
    def handle_data(self,data):
        if self.current is not None: self.current['text']+=data
    def handle_endtag(self,tag):
        if tag=='label':
            self.labels.append(self.current)
            self.current=None
p=Page()
p.feed(render())
assert p.attrs and any(x['text'].strip()=='Show archived invoices' and (x['wraps'] or (x['for'] and x['for']==p.attrs.get('id'))) for x in p.labels)
assert all('Updated' not in x['text'] for x in p.labels)

